selector_to_html = {"a[href=\"#install-the-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3. Install the package<a class=\"headerlink\" href=\"#install-the-package\" title=\"Link to this heading\">#</a></h3><p>FlagGems can be installed either a pure Python package or a package with C++ extensions.\nThe C++ extensions are  still an experimental feature, so please make sure\nyou have conducted some assessments before using them in production environments.</p>", "a[href=\"#scikit-build-core-options-scikit-build-core-options\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.4 <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> options {#scikit-build-core-options}<a class=\"headerlink\" href=\"#scikit-build-core-options-scikit-build-core-options\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> tool is a build-backend that bridges the CMake\nand the Python build system, making it easier to create Python modules with CMake.\nSome commonly used environemnt variables for configuring <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> inlcude:</p>", "a[href=\"#the-libtriton-jit-library-libtriton-jit\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.5 The <code class=\"docutils literal notranslate\"><span class=\"pre\">libtriton_jit</span></code> library  {#libtriton-jit}<a class=\"headerlink\" href=\"#the-libtriton-jit-library-libtriton-jit\" title=\"Link to this heading\">#</a></h3><p>The C++ extension of FlagGems depends on <a class=\"reference external\" href=\"https://github.com/flagos-ai/libtriton_jit/\">TritonJIT</a>,\nwhich is a library that implements a Triton JIT runtime in C++\nand enables calling Triton JIT functions from C++ code.\nIf you are building/inistalling <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> with an external TritonJIT,\nyou should build and install it as a precondition and then\npass the option <code class=\"docutils literal notranslate\"><span class=\"pre\">-DTritonJIT_ROOT=&lt;install</span> <span class=\"pre\">path&gt;</span></code> to CMake.</p><p>For example, the following command triggers an editable installation\nwith external <em>Triton JIT</em> installed  at <code class=\"docutils literal notranslate\"><span class=\"pre\">/usr/local/lib/libtriton_jit</span></code>:</p>", "a[href=\"#clone-the-source\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1. Clone the source<a class=\"headerlink\" href=\"#clone-the-source\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#prerequisites\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#build-and-install-from-source-install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Build and install from source {#install-from-source}<a class=\"headerlink\" href=\"#build-and-install-from-source-install-from-source\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> can be built and installed from source just like any other\nopen source software.</p>", "a[href=\"#install-flagtree\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2. Install FlagTree<a class=\"headerlink\" href=\"#install-flagtree\" title=\"Link to this heading\">#</a></h3><p>If you want to use the vanilla Triton compiler instead of <em>FlagTree</em>, you can skip this step.</p><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/flagtree/\">FlagTree</a> is an open source,\nunified compiler for multiple AI platforms. Please make sure you have\nread the environment requirements from the FlagTree project before\ninstalling it.</p>", "a[href=\"#frequently-used-pip-options-pip-options\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.1 Frequently used <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> options  {#pip-options}<a class=\"headerlink\" href=\"#frequently-used-pip-options-pip-options\" title=\"Link to this heading\">#</a></h3><p>Some commonly used <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> options are:</p>", "a[href=\"../usage/non-nvidia.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Running FlagGems on Non-NVIDIA Hardware<a class=\"headerlink\" href=\"#running-flaggems-on-non-nvidia-hardware\" title=\"Link to this heading\">#</a></h1><h2>1. Supported platforms<a class=\"headerlink\" href=\"#supported-platforms\" title=\"Link to this heading\">#</a></h2><p>FlagGems supports a range of AI chips/platforms beyond NVIDIA.\nFor an up-to-date list of validated platforms, please refer to\n<a class=\"reference internal\" href=\"../overview/platforms.html\"><span class=\"doc std std-doc\">Supported Platforms</span></a></p>", "a[href=\"#install-from-pypi\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Install from PyPI<a class=\"headerlink\" href=\"#install-from-pypi\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> can be installed from <a class=\"reference external\" href=\"https://pypi.org/project/flag-gems/\">PyPI</a>\nusing your favorite Python package manager (e.g. <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code>).</p>", "a[href=\"#references\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. References<a class=\"headerlink\" href=\"#references\" title=\"Link to this heading\">#</a></h2><h3>4.1 Frequently used <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> options  {#pip-options}<a class=\"headerlink\" href=\"#frequently-used-pip-options-pip-options\" title=\"Link to this heading\">#</a></h3><p>Some commonly used <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> options are:</p>", "a[href=\"#about-cmake-options-cmake-options\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.3 About CMake options  {#cmake-options}<a class=\"headerlink\" href=\"#about-cmake-options-cmake-options\" title=\"Link to this heading\">#</a></h3><p>As mentioned before, you can enable the C++ extensions when building/installing\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> by passing arguments to CMake via the <code class=\"docutils literal notranslate\"><span class=\"pre\">SKBUILD_CMAKE_ARGS</span></code> or\nthe <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code> environment variable.\nNote that, for the environment variable <code class=\"docutils literal notranslate\"><span class=\"pre\">SKBUILD_CMAKE_ARGS</span></code>, multiple options\nare separated by semicolons (<code class=\"docutils literal notranslate\"><span class=\"pre\">;</span></code>), whereas for <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code>, they are separated by spaces.\nThis relates to the difference between <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> and its predecessor,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build</span></code>.</p><p>The CMake options for configuring <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> are listed below:</p>", "a[href=\"#installing-flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installing FlagGems<a class=\"headerlink\" href=\"#installing-flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#install-the-python-package-only\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">3.3.2 Install the Python package only<a class=\"headerlink\" href=\"#install-the-python-package-only\" title=\"Link to this heading\">#</a></h4><p>You can install <em>flag_gems</em> as a pure Python package.\nIf you are using <em>FlagGems</em> as is with no intent to customize it,\nyou can install the package to your Python environment:</p>", "a[href=\"#build-isolation-build-isolation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.2 Build isolation  {#build-isolation}<a class=\"headerlink\" href=\"#build-isolation-build-isolation\" title=\"Link to this heading\">#</a></h3><p>Following the community recommendations for build frontends in\n<a class=\"reference external\" href=\"https://peps.python.org/pep-0517/#recommendations-for-build-frontends-non-normative\">PEP 517</a>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> or other modern build frontends uses an isolated environment to build packages.\nThis involves creating a virtual environment and installing the build requirements in it\nbefore building the package.</p><p>If you do not want build isolation (often in the case with editable installation),\nyou can pass <code class=\"docutils literal notranslate\"><span class=\"pre\">--no-build-isolation</span></code> flag to <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">install</span></code>.\nIn this case, the installer will attempt to reuse any existing, compatible\npackages when it identifies a dependency to install.\nThis means you will need\nto install <code class=\"docutils literal notranslate\"><span class=\"pre\">build-requirements</span></code> in your current environment beforehand.\nCheck the <code class=\"docutils literal notranslate\"><span class=\"pre\">[build-system.requires]</span></code> section in the <code class=\"docutils literal notranslate\"><span class=\"pre\">pyproject.toml</span></code> file and\ninstall the required packages.</p>", "a[href=\"#install-with-c-extension\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">3.3.1 Install with C++ extension<a class=\"headerlink\" href=\"#install-with-c-extension\" title=\"Link to this heading\">#</a></h4><p>If you are NOT enabling the C++ wrapped operators, you can skip to the next step.</p><p>To build and install the C++ extensions in <em>FlagGems</em>, the CMake option\n<code class=\"docutils literal notranslate\"><span class=\"pre\">-DFLAGGEMS_BUILD_C_EXTENSION=ON</span></code> must be specified during installation.\nThis can be done by passing arguments to CMake via the <code class=\"docutils literal notranslate\"><span class=\"pre\">SKBUILD_CMAKE_ARGS</span></code> or\nthe <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code> environment variable.\nThe following command installs the <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> package in an editable mode,\nwhile enabling the C++ extensions using the <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code> environment variable:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
